[9077] = { en = "Bonescythe Breastplate", tier = 4,
  t = "Bonescythe-borstplaat",
  d = "Als je Bonescythe wilt laten maken, moet je zelf de materialen leveren.$B$BGa Naxxramas binnen, die grote zwevende stad van de dood daarboven in de lucht. Zoek daar ontheiligde wapenrusting en door oorlog gehavende stukken wapenrusting. Breng die terug, samen met de materialen om alles in elkaar te zetten. Dan krijg je je Bonescythe. O ja, en je moet me ook betalen voor de moeite... De botten lever ik zelf.",
  o = "Rohan the Assassin in Light's Hope Chapel in de Eastern Plaguelands maakt een Bonescythe Breastplate voor je als je hem het volgende brengt: 1 Desecrated Breastplate, 25 Wartorn Leather Scraps, 2 Arcanite Bars en 6 Cured Rugged Hides.",
  p = "Je mist nog een paar onderdelen voor deze opdracht. Ga ze allemaal halen!",
  c = "Uitstekend, $N!$BJe hebt alles gebracht, precies zoals ik vroeg. Nu kan ik een Bonescythe Breastplate maken.",
  g = { {"leveren", "to supply, deliver"}, {"zwevende", "floating (zweven)"}, {"daarboven", "up there"}, {"ontheiligde", "desecrated (ontheiligen)"}, {"gehavende", "battered, worn (gehavend)"}, {"in elkaar te zetten", "to put together (in elkaar zetten)"}, {"moeite", "trouble, effort"}, {"botten", "bones (bot)"}, {"lever", "supply (leveren)"}, {"onderdelen", "parts (onderdeel)"}, {"precies", "exactly"} },
},

