[9086] = { en = "Dreamwalker Tunic", tier = 4,
  t = "Dreamwalker-tuniek",
  d = "Veel helden zijn gevallen in de laatste oorlog. En tot op de dag van vandaag komen er nog steeds velen om door de Scourge. Van de lijken van de gevallenen wordt de wapenrusting afgehaald. Die wordt naar Naxxramas gebracht, voor onbekende doeleinden.$B$BHaal de ontheiligde wapenrusting en de door oorlog gehavende stukken wapenrusting terug. Breng me ook de andere materialen die ik nodig heb, dan maak ik Dreamwalker-wapenrusting.",
