  p = "De materialen kosten veel, maar dat ben je snel vergeten.",
  c = "Je Dreamwalker Tunic is klaar, $N.",
  g = { {"komen", "come; komen om = die, perish (omkomen)"}, {"lijken", "corpses (lijk)"}, {"gevallenen", "the fallen"}, {"wapenrusting", "armour"}, {"afgehaald", "stripped, taken off (afhalen)"}, {"doeleinden", "purposes (doeleinde)"}, {"ontheiligde", "desecrated (ontheiligen)"}, {"gehavende", "battered, worn (gehavend)"}, {"materialen", "materials (materiaal)"} },
},

